        "code": "def main(response_body: str):
	import json
	try:
		data = json.loads(response_body)
		if 'tree' not in data:
			return {'file_structure': 'Error: Unable to parse repository structure'}

		tree = data['tree']
		tree_sorted = sorted(tree, key=lambda x: x.get('path', ''))

		lines = []
		path_stack = []

		for item in tree_sorted:
			path = item.get('path', '')
			item_type = item.get('type', '')
			parts = path.split('/')
			depth = len(parts)
			name = parts[-1]

			while len(path_stack) >= depth:
				path_stack.pop()
			path_stack.append(name)

			if depth == 1:
				prefix = ''
			else:
				prefix = '  ' * (depth - 1)

			if item_type == 'tree':
				lines.append(f'{prefix}├── {name}/')
			else:
				lines.append(f'{prefix}├── {name}')

		file_structure = '\n'.join(lines)

	except Exception as e:
		file_structure = f'Error: {str(e)}'

	return {
		'file_structure': file_structure
	}"
