    {
      "id": "14",
      "type": "code",
      "param": {
        "variables": [
          ["dates", ["order_date", "13"]],
          ["profits", ["profit_values", "13"]]
        ],
        "outputs": [
          ["quarters", "string"],
          ["quarterly_profits", "string"]
        ],
        "code": "def main(dates: str, profits: str):\n\tfrom datetime import datetime\n\tfrom collections import defaultdict\n\t\n\tdate_list = dates.split(';')\n\tprofit_list = [float(p) for p in profits.split(';')]\n\t\n\tquarterly_data = defaultdict(float)\n\t\n\tfor date_str, profit in zip(date_list, profit_list):\n\t\ttry:\n\t\t\tdate_obj = datetime.strptime(date_str.strip(), '%Y-%m-%d')\n\t\texcept:\n\t\t\ttry:\n\t\t\t\tdate_obj = datetime.strptime(date_str.strip(), '%m/%d/%Y')\n\t\t\texcept:\n\t\t\t\tcontinue\n\t\t\n\t\tyear = date_obj.year\n\t\tquarter = (date_obj.month - 1) // 3 + 1\n\t\tquarter_key = f\"Q{quarter} {year}\"\n\t\tquarterly_data[quarter_key] += profit\n\t\n\tsorted_quarters = sorted(quarterly_data.items(), key=lambda x: (int(x[0].split()[1]), int(x[0][1])))\n\t\n\tquarters_str = ';'.join([q[0] for q in sorted_quarters])\n\tprofits_str = ';'.join([str(round(q[1], 2)) for q in sorted_quarters])\n\t\n\treturn {\n\t\t\"quarters\": quarters_str,\n\t\t\"quarterly_profits\": profits_str\n\t}"
      }
