        "code": "def main(categories: list, resume_texts: list, resumes: list) -> dict:\n\taccountant_list = []\n\tarts_list = []\n\tsales_list = []\n\tteacher_list = []\n\taccountant_files = []\n\tarts_files = []\n\tsales_files = []\n\tteacher_files = []\n\t\n\tfor i, cat in enumerate(categories):\n\t\tif cat == 'ACCOUNTANT':\n\t\t\taccountant_list.append(resume_texts[i])\n\t\t\taccountant_files.append(resumes[i])\n\t\telif cat == 'ARTS':\n\t\t\tarts_list.append(resume_texts[i])\n\t\t\tarts_files.append(resumes[i])\n\t\telif cat == 'SALES':\n\t\t\tsales_list.append(resume_texts[i])\n\t\t\tsales_files.append(resumes[i])\n\t\telif cat == 'TEACHER':\n\t\t\tteacher_list.append(resume_texts[i])\n\t\t\tteacher_files.append(resumes[i])\n\t\n\treturn {\n\t\t\"accountant_texts\": '\\n\\n---RESUME---\\n\\n'.join(accountant_list) if accountant_list else 'No resumes',\n\t\t\"arts_texts\": '\\n\\n---RESUME---\\n\\n'.join(arts_list) if arts_list else 'No resumes',\n\t\t\"sales_texts\": '\\n\\n---RESUME---\\n\\n'.join(sales_list) if sales_list else 'No resumes',\n\t\t\"teacher_texts\": '\\n\\n---RESUME---\\n\\n'.join(teacher_list) if teacher_list else 'No resumes',\n\t\t\"accountant_file\": {'files': accountant_files, 'count': len(accountant_files)},\n\t\t\"arts_file\": {'files': arts_files, 'count': len(arts_files)},\n\t\t\"sales_file\": {'files': sales_files, 'count': len(sales_files)},\n\t\t\"teacher_file\": {'files': teacher_files, 'count': len(teacher_files)}\n\t}"
