        "code": "def main(acc_result: str, arts_result: str, sales_result: str, teacher_result: str, acc_data: dict, arts_data: dict, sales_data: dict, teacher_data: dict) -> dict:\n\timport re\n\t\n\tdef extract_info(result_text):\n\t\tidx_match = re.search(r'BEST_INDEX:\\s*(\\d+)', result_text)\n\t\treason_match = re.search(r'REASON:\\s*(.+)', result_text, re.DOTALL)\n\t\tidx = int(idx_match.group(1)) if idx_match else 0\n\t\treason = reason_match.group(1).strip() if reason_match else result_text\n\t\treturn idx, reason\n\t\n\tbest_files = []\n\treasons = {}\n\t\n\tif acc_data['count'] > 0:\n\t\tidx, reason = extract_info(acc_result)\n\t\tbest_files.append(acc_data['files'][min(idx, acc_data['count']-1)])\n\t\treasons['acc'] = reason\n\telse:\n\t\treasons['acc'] = 'No ACCOUNTANT resumes available'\n\t\n\tif arts_data['count'] > 0:\n\t\tidx, reason = extract_info(arts_result)\n\t\tbest_files.append(arts_data['files'][min(idx, arts_data['count']-1)])\n\t\treasons['arts'] = reason\n\telse:\n\t\treasons['arts'] = 'No ARTS resumes available'\n\t\n\tif sales_data['count'] > 0:\n\t\tidx, reason = extract_info(sales_result)\n\t\tbest_files.append(sales_data['files'][min(idx, sales_data['count']-1)])\n\t\treasons['sales'] = reason\n\telse:\n\t\treasons['sales'] = 'No SALES resumes available'\n\t\n\tif teacher_data['count'] > 0:\n\t\tidx, reason = extract_info(teacher_result)\n\t\tbest_files.append(teacher_data['files'][min(idx, teacher_data['count']-1)])\n\t\treasons['teacher'] = reason\n\telse:\n\t\treasons['teacher'] = 'No TEACHER resumes available'\n\t\n\treturn {\n\t\t\"best_resumes\": best_files,\n\t\t\"acc_reason\": reasons['acc'],\n\t\t\"arts_reason\": reasons['arts'],\n\t\t\"sales_reason\": reasons['sales'],\n\t\t\"teacher_reason\": reasons['teacher']\n\t}"
